package main

import (
	"net"
	"sync"

	"golang.zx2c4.com/wireguard/conn"
)

func udpBind(loopbackOnly bool) conn.Bind {
	if loopbackOnly {
		return &loopbackBind{}
	}
	return conn.NewDefaultBind()
}

// Local recipes only use IPv4 loopback, including the remote address
// generated by the Kiara fixture. Keep their UDP socket off external interfaces.
type loopbackBind struct {
	conn.StdNetBind
	mu     sync.Mutex
	socket *net.UDPConn
}

func (b *loopbackBind) Open(port uint16) ([]conn.ReceiveFunc, uint16, error) {
	b.mu.Lock()
	defer b.mu.Unlock()
	if b.socket != nil {
		return nil, 0, conn.ErrBindAlreadyOpen
	}
	socket, err := net.ListenUDP("udp4", &net.UDPAddr{IP: net.IPv4(127, 0, 0, 1), Port: int(port)})
	if err != nil {
		return nil, 0, err
	}
	b.socket = socket
	return []conn.ReceiveFunc{func(packets [][]byte, sizes []int, endpoints []conn.Endpoint) (int, error) {
		size, addr, err := socket.ReadFromUDPAddrPort(packets[0])
		if err != nil {
			return 0, err
		}
		sizes[0] = size
		endpoints[0] = &conn.StdNetEndpoint{AddrPort: addr}
		return 1, nil
	}}, socket.LocalAddr().(*net.UDPAddr).AddrPort().Port(), nil
}

func (b *loopbackBind) Close() error {
	b.mu.Lock()
	defer b.mu.Unlock()
	if b.socket == nil {
		return nil
	}
	socket := b.socket
	b.socket = nil
	return socket.Close()
}

func (*loopbackBind) BatchSize() int       { return 1 }
func (*loopbackBind) SetMark(uint32) error { return nil }

func (b *loopbackBind) Send(packets [][]byte, endpoint conn.Endpoint) error {
	peer, ok := endpoint.(*conn.StdNetEndpoint)
	if !ok || !peer.AddrPort.Addr().IsLoopback() || !peer.AddrPort.Addr().Is4() {
		return conn.ErrWrongEndpointType
	}
	b.mu.Lock()
	socket := b.socket
	b.mu.Unlock()
	if socket == nil {
		return net.ErrClosed
	}
	for _, packet := range packets {
		if _, err := socket.WriteToUDPAddrPort(packet, peer.AddrPort); err != nil {
			return err
		}
	}
	return nil
}
